import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createMockProvider} from '../providers/mock/index.js';
import type {ChatSession} from '../types/session.js';

it('reports a rejected string as an Error with its original cause [specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const errors: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Assistant'}),
    undefined,
    {
      hooks: {
        beforeUserInput: async () => Promise.reject('input rejected'),
        onError: async (_session, error) => {
          errors.push(error);
        },
      },
    }
  );

  const outcome = await orchestrator.processMessage(session).then(
    value => ({resolved: value}),
    (reason: unknown) => ({rejected: reason})
  );

  expect({outcome, count: errors.length, isError: errors[0] instanceof Error, message: errors[0]?.message, cause: errors[0]?.cause}).toEqual({
    outcome: {rejected: 'input rejected'},
    count: 1,
    isError: true,
    message: 'input rejected',
    cause: 'input rejected',
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"
